import { describe, expect, it } from "vitest";
import { POLL_FALLBACK_REFRESH_MS, parseExperimentEvent, SETTLE_AFTER_FINISH_MS, STALL_AFTER_MS, STREAM_FALLBACK_REFRESH_MS, splitSseData, watchRunningExperiments, } from "./watchRunningExperiments.js";
const SESSION = "session-1";
const A = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
const B = "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb";
function status(experimentId, overrides = {}) {
    return {
        experimentId,
        status: "pending",
        finishedCount: 0,
        remainingCount: 4,
        traceCount: 0,
        resumable: true,
        ...overrides,
    };
}
function sequence(values) {
    const queue = [...values];
    return () => (queue.length > 1 ? queue.shift() : queue[0]);
}
function fakeDeps(opts) {
    let clock = 0;
    const nextList = sequence(opts.lists);
    const perExperiment = Object.fromEntries(Object.entries(opts.statuses ?? {}).map(([id, list]) => [
        id,
        sequence(list),
    ]));
    let captured;
    let streamSignal;
    const deps = {
        agentSessionId: SESSION,
        snapshots: [],
        waits: [],
        wakes: [],
        streamsOpened: 0,
        createdAfters: [],
        streamAborted: () => streamSignal?.aborted ?? false,
        listExperiments: async (createdAfter) => {
            deps.createdAfters.push(createdAfter);
            const next = nextList();
            if (next instanceof Error) {
                throw next;
            }
            return next;
        },
        readStatus: async (id) => {
            const next = perExperiment[id];
            if (!next) {
                throw new Error(`no status for ${id}`);
            }
            return next();
        },
        experimentUrl: (id) => `https://bitfab.test/experiments?experimentIds=${id}`,
        openStream: (onEvent, signal) => {
            deps.streamsOpened += 1;
            captured = onEvent;
            streamSignal = signal;
            if (opts.stream === "unavailable") {
                return Promise.resolve("unavailable");
            }
            return new Promise((resolve) => {
                signal.addEventListener("abort", () => resolve("ended"));
            });
        },
        emit: (snapshot) => {
            deps.snapshots.push(snapshot);
        },
        now: () => clock,
        wait: async (ms, wake) => {
            let woken = false;
            void wake.then(() => {
                woken = true;
            });
            if (captured && opts.duringWait) {
                opts.duringWait(captured);
            }
            await new Promise((resolve) => setTimeout(resolve, 0));
            deps.waits.push(ms);
            deps.wakes.push(woken);
            clock += ms;
        },
    };
    return deps;
}
describe("watchRunningExperiments", () => {
    it("makes one list call and exits when nothing runs and no discovery is asked", async () => {
        const deps = fakeDeps({ lists: [[]] });
        const final = await watchRunningExperiments(0, deps);
        expect(final).toEqual({ running: [], finished: [] });
        expect(deps.snapshots).toEqual([{ running: [], finished: [] }]);
        expect(deps.streamsOpened).toBe(0);
        expect(deps.waits).toEqual([]);
    });
    it("reports progress, then the finish, and closes the stream", async () => {
        const deps = fakeDeps({
            lists: [[{ id: A, name: "shorter prompt" }], []],
            statuses: {
                [A]: [
                    status(A, { finishedCount: 2, remainingCount: 2 }),
                    status(A, {
                        status: "completed",
                        finishedCount: 4,
                        remainingCount: 0,
                    }),
                ],
            },
        });
        await watchRunningExperiments(0, deps);
        expect(deps.snapshots).toEqual([
            {
                running: [
                    {
                        id: A,
                        name: "shorter prompt",
                        finished: 2,
                        total: 4,
                        url: `https://bitfab.test/experiments?experimentIds=${A}`,
                        stalled: false,
                    },
                ],
                finished: [],
            },
            {
                running: [],
                finished: [
                    {
                        id: A,
                        name: "shorter prompt",
                        status: "completed",
                        url: `https://bitfab.test/experiments?experimentIds=${A}`,
                    },
                ],
            },
        ]);
        expect(deps.streamsOpened).toBe(1);
        expect(deps.streamAborted()).toBe(true);
        expect(deps.waits[0]).toBe(STREAM_FALLBACK_REFRESH_MS);
    });
    it("announces an experiment that started and finished between two looks", async () => {
        const deps = fakeDeps({
            lists: [[], [{ id: A, name: "quick" }]],
            statuses: { [A]: [status(A, { status: "completed" })] },
        });
        await watchRunningExperiments(30_000, deps);
        expect(deps.createdAfters[0]).toEqual(expect.any(String));
        expect(deps.snapshots.at(-1)).toEqual({
            running: [],
            finished: [
                {
                    id: A,
                    name: "quick",
                    status: "completed",
                    url: `https://bitfab.test/experiments?experimentIds=${A}`,
                },
            ],
        });
    });
    it("asks only for running experiments when it is not looking for a new one", async () => {
        const deps = fakeDeps({ lists: [[]] });
        await watchRunningExperiments(0, deps);
        expect(deps.createdAfters).toEqual([null]);
    });
    it("stops soon after its experiments finish instead of waiting out the look-ahead", async () => {
        const deps = fakeDeps({
            lists: [[{ id: A, name: null }], []],
            statuses: {
                [A]: [status(A), status(A, { status: "completed" })],
            },
        });
        await watchRunningExperiments(120_000, deps);
        const waited = deps.waits.reduce((total, ms) => total + ms, 0);
        expect(waited).toBeLessThan(120_000);
        expect(waited).toBeLessThanOrEqual(STREAM_FALLBACK_REFRESH_MS + SETTLE_AFTER_FINISH_MS);
        expect(deps.snapshots.at(-1)?.finished[0]).toMatchObject({
            id: A,
            status: "completed",
        });
    });
    it("marks a running experiment stalled after ten minutes without progress, and not while it is being graded", async () => {
        const stuck = status(A, { finishedCount: 2, remainingCount: 3 });
        const grading = status(B, { finishedCount: 4, remainingCount: 0 });
        const minutes = Math.ceil(STALL_AFTER_MS / STREAM_FALLBACK_REFRESH_MS) + 2;
        const deps = fakeDeps({
            lists: [
                ...Array.from({ length: minutes }, () => [
                    { id: A, name: null },
                    { id: B, name: null },
                ]),
                [],
            ],
            statuses: {
                [A]: [
                    ...Array.from({ length: minutes }, () => stuck),
                    status(A, { status: "completed" }),
                ],
                [B]: [
                    ...Array.from({ length: minutes }, () => grading),
                    status(B, { status: "completed" }),
                ],
            },
        });
        await watchRunningExperiments(0, deps);
        const flagged = deps.snapshots.find((snapshot) => snapshot.running.some((experiment) => experiment.stalled));
        expect(flagged?.running.find((one) => one.id === A)?.stalled).toBe(true);
        expect(flagged?.running.find((one) => one.id === B)?.stalled).toBe(false);
        expect(deps.snapshots[0]?.running.every((one) => !one.stalled)).toBe(true);
    });
    it("keeps looking for a starting experiment while discovery lasts", async () => {
        const deps = fakeDeps({
            lists: [[], [{ id: A, name: null }], []],
            statuses: {
                [A]: [
                    status(A, { remainingCount: null }),
                    status(A, { status: "failed" }),
                ],
            },
        });
        await watchRunningExperiments(30_000, deps);
        expect(deps.snapshots[1]?.running[0]).toMatchObject({
            id: A,
            total: null,
        });
        expect(deps.snapshots.at(-1)?.finished[0]).toMatchObject({
            id: A,
            status: "failed",
        });
        expect(deps.streamsOpened).toBe(1);
    });
    it("wakes on events for its own experiments and ignores other sessions", async () => {
        const events = [
            { experimentId: B, agentSessionId: "someone-else" },
            { experimentId: A, agentSessionId: null },
        ];
        const deps = fakeDeps({
            lists: [[{ id: A, name: null }], [{ id: A, name: null }], [], []],
            statuses: {
                [A]: [status(A), status(A), status(A, { status: "completed" })],
            },
            duringWait: (onEvent) => {
                const event = events.shift();
                if (event) {
                    onEvent(event);
                }
            },
        });
        await watchRunningExperiments(0, deps);
        expect(deps.wakes.slice(0, 2)).toEqual([false, true]);
    });
    it("falls back to a slower poll when the server has no event stream", async () => {
        const deps = fakeDeps({
            lists: [[{ id: A, name: null }], [{ id: A, name: null }], []],
            statuses: {
                [A]: [status(A), status(A), status(A, { status: "completed" })],
            },
            stream: "unavailable",
        });
        await watchRunningExperiments(0, deps);
        expect(deps.wakes[0]).toBe(true);
        expect(deps.waits).toContain(POLL_FALLBACK_REFRESH_MS);
    });
    it("rides out one failed refresh and stops after three in a row", async () => {
        const recovering = fakeDeps({
            lists: [new Error("blip"), []],
        });
        await expect(watchRunningExperiments(0, recovering)).resolves.toEqual({
            running: [],
            finished: [],
        });
        expect(recovering.snapshots).toHaveLength(1);
        const neverRead = fakeDeps({ lists: [new Error("down")] });
        await expect(watchRunningExperiments(0, neverRead)).rejects.toThrow("down");
        expect(neverRead.snapshots).toEqual([]);
    });
});
describe("splitSseData", () => {
    it("returns each complete message's event and data and keeps the partial tail", () => {
        const { messages, rest } = splitSseData('event: experiment:updated\ndata: {"a":1}\n\n: comment\n\nevent: ping\ndata: {"b"');
        expect(messages).toEqual([{ event: "experiment:updated", data: '{"a":1}' }]);
        expect(rest).toBe('event: ping\ndata: {"b"');
    });
});
describe("parseExperimentEvent", () => {
    it("reads the experiment id and the session that launched it", () => {
        expect(parseExperimentEvent({
            event: "experiment:updated",
            data: JSON.stringify({
                experimentId: A,
                experiment: { agentSessionId: SESSION },
            }),
        })).toEqual({ experimentId: A, agentSessionId: SESSION });
    });
    it("reads the old testRunId key", () => {
        expect(parseExperimentEvent({
            event: "experiment-stats:updated",
            data: JSON.stringify({ testRunId: A }),
        })).toEqual({ experimentId: A, agentSessionId: null });
    });
    it("drops pings, other event types, and unreadable data", () => {
        expect(parseExperimentEvent({ event: "ping", data: "{}" })).toBeNull();
        expect(parseExperimentEvent({
            event: "label:updated",
            data: JSON.stringify({ experimentId: A }),
        })).toBeNull();
        expect(parseExperimentEvent({ event: "experiment:updated", data: "not json" })).toBeNull();
        expect(parseExperimentEvent({
            event: null,
            data: JSON.stringify({ experimentId: A }),
        })).toBeNull();
    });
});
